/**
 * Gas-refund parameters the caller commits into every chain's `safeTxHash`.
 * mobile-core does not invent the economics — the caller supplies the token,
 * the USDC-per-gas reimbursement rate, and the gas ceilings (e.g. from a
 * deploy quote / its own policy).
 */
public struct DirectGasFfi {
    /**
     * ERC-20 gas token (USDC) the Safe reimburses the relayer in.
     */
    public var gasToken: String
    /**
     * USDC-per-gas reimbursement rate, hex `0x...` U256.
     */
    public var gasPriceHex: String
    /**
     * Inner-action gas forwarded to `execTransaction` (`safeTxGas`).
     */
    public var safeTxGas: UInt64
    /**
     * Safe overhead reimbursed on top of measured gas (`baseGas`).
     */
    public var baseGas: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * ERC-20 gas token (USDC) the Safe reimburses the relayer in.
         */gasToken: String, 
        /**
         * USDC-per-gas reimbursement rate, hex `0x...` U256.
         */gasPriceHex: String, 
        /**
         * Inner-action gas forwarded to `execTransaction` (`safeTxGas`).
         */safeTxGas: UInt64, 
        /**
         * Safe overhead reimbursed on top of measured gas (`baseGas`).
         */baseGas: UInt64) {
        self.gasToken = gasToken
        self.gasPriceHex = gasPriceHex
        self.safeTxGas = safeTxGas
        self.baseGas = baseGas
    }
}

#if compiler(>=6)
extension DirectGasFfi: Sendable {}
#endif


extension DirectGasFfi: Equatable, Hashable {
    public static func ==(lhs: DirectGasFfi, rhs: DirectGasFfi) -> Bool {
        if lhs.gasToken != rhs.gasToken {
            return false
        }
        if lhs.gasPriceHex != rhs.gasPriceHex {
            return false
        }
        if lhs.safeTxGas != rhs.safeTxGas {
            return false
        }
        if lhs.baseGas != rhs.baseGas {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(gasToken)
        hasher.combine(gasPriceHex)
        hasher.combine(safeTxGas)
        hasher.combine(baseGas)
    }
}



