/**
 * All inputs to [`prepare_direct_transfer`], bundled into one record.
 *
 * This is passed as a SINGLE by-value buffer across the FFI on purpose. The
 * previous shape took thirteen loose arguments (eleven of them by-value
 * `RustBuffer` structs); on Android arm64 the JNA/libffi marshalling of that
 * many by-value struct arguments faulted with a native null-pointer dereference
 * inside the UniFFI argument-lowering scaffolding, before any Rust logic ran
 * (dev-workspace #217). Collapsing every input into one record reduces the call
 * to the same narrow "one record in" shape the other async exports use safely.
 */
public struct DirectTransferRequestFfi {
    public var chainId: UInt64
    public var rpcUrl: String
    public var safe: String
    public var webauthnSigner: String
    public var to: String
    public var valueHex: String
    public var dataHex: String
    public var gas: DirectGasFfi
    public var paymentUsdcHex: String
    public var transferToken: String?
    public var transferAmountHex: String
    public var relayerAddress: String
    public var relayerBaseUrl: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(chainId: UInt64, rpcUrl: String, safe: String, webauthnSigner: String, to: String, valueHex: String, dataHex: String, gas: DirectGasFfi, paymentUsdcHex: String, transferToken: String?, transferAmountHex: String, relayerAddress: String, relayerBaseUrl: String) {
        self.chainId = chainId
        self.rpcUrl = rpcUrl
        self.safe = safe
        self.webauthnSigner = webauthnSigner
        self.to = to
        self.valueHex = valueHex
        self.dataHex = dataHex
        self.gas = gas
        self.paymentUsdcHex = paymentUsdcHex
        self.transferToken = transferToken
        self.transferAmountHex = transferAmountHex
        self.relayerAddress = relayerAddress
        self.relayerBaseUrl = relayerBaseUrl
    }
}

