/**
 * The EVM chains an owner op applies to, plus this device's own signer
 * addresses. Built with [`evm_targets_from_report`] rather than by hand.
 */
public struct EvmOwnerTargetsFfi {
    public var chains: [ChainOwnerStateFfi]
    public var ownReprs: [String]
    /**
     * Deployed EVM chains whose owner set could NOT be read. Their presence
     * blocks every owner op: one change applies to all chains at once, so a
     * chain missing from `chains` is one the checks were answered without.
     */
    public var unreadable: [UnreadableChainFfi]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(chains: [ChainOwnerStateFfi], ownReprs: [String], 
        /**
         * Deployed EVM chains whose owner set could NOT be read. Their presence
         * blocks every owner op: one change applies to all chains at once, so a
         * chain missing from `chains` is one the checks were answered without.
         */unreadable: [UnreadableChainFfi]) {
        self.chains = chains
        self.ownReprs = ownReprs
        self.unreadable = unreadable
    }
}

