extension EvmOwnerTargetsFfi: Sendable {}
#endif


extension EvmOwnerTargetsFfi: Equatable, Hashable {
    public static func ==(lhs: EvmOwnerTargetsFfi, rhs: EvmOwnerTargetsFfi) -> Bool {
        if lhs.chains != rhs.chains {
            return false
        }
        if lhs.ownReprs != rhs.ownReprs {
            return false
        }
        if lhs.unreadable != rhs.unreadable {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(chains)
        hasher.combine(ownReprs)
        hasher.combine(unreadable)
    }
}



