        if lhs.pubkeyB58 != rhs.pubkeyB58 {
            return false
        }
        if lhs.seedB64 != rhs.seedB64 {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(pubkeyB58)
        hasher.combine(seedB64)
    }
}



