    public static func ==(lhs: LightningWithdrawalPlanFfi, rhs: LightningWithdrawalPlanFfi) -> Bool {
        if lhs.closes != rhs.closes {
            return false
        }
        if lhs.send != rhs.send {
            return false
        }
        if lhs.returningAfterCloseSats != rhs.returningAfterCloseSats {
