        }
        if lhs.unconfirmedOnchainSats != rhs.unconfirmedOnchainSats {
            return false
        }
        if lhs.inChannelsSats != rhs.inChannelsSats {
            return false
        }
        if lhs.returningSats != rhs.returningSats {
            return false
        }
        if lhs.returning != rhs.returning {
