/**
 * A logical wallet owner, identified by its WebAuthn passkey. The same passkey
 * is the owner on every chain, but each chain family stores its own
 * representation of it; [`reprs`](Self::reprs) holds every representation the
 * caller derived, so the model matches an identity against a chain's on-chain
 * owner set by set membership and needs no crypto of its own.
 */
public struct OwnerIdentityFfi {
    public var webauthnPubkeyHex: String
    public var label: String?
    public var isThisDevice: Bool
    /**
     * Compared case-insensitively.
     */
    public var reprs: OwnerReprsFfi
    /**
     * The EVM address to ENROL when adding this identity as a Safe owner: the
     * `BatchWebAuthnSigner`, the only representation that can validate the
     * Merkle-rooted multichain signature every owner op is signed with.
     * [`reprs`](Self::reprs) is an unordered match/display set and cannot say
     * which member is the batch one, so it is carried separately. `None` when
     * the batch address could not be derived.
     */
    public var evmEnrollRepr: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(webauthnPubkeyHex: String, label: String?, isThisDevice: Bool, 
        /**
         * Compared case-insensitively.
         */reprs: OwnerReprsFfi, 
        /**
         * The EVM address to ENROL when adding this identity as a Safe owner: the
         * `BatchWebAuthnSigner`, the only representation that can validate the
         * Merkle-rooted multichain signature every owner op is signed with.
         * [`reprs`](Self::reprs) is an unordered match/display set and cannot say
         * which member is the batch one, so it is carried separately. `None` when
         * the batch address could not be derived.
         */evmEnrollRepr: String?) {
        self.webauthnPubkeyHex = webauthnPubkeyHex
        self.label = label
        self.isThisDevice = isThisDevice
        self.reprs = reprs
        self.evmEnrollRepr = evmEnrollRepr
    }
}

#if compiler(>=6)
extension OwnerIdentityFfi: Sendable {}
#endif


extension OwnerIdentityFfi: Equatable, Hashable {
    public static func ==(lhs: OwnerIdentityFfi, rhs: OwnerIdentityFfi) -> Bool {
        if lhs.webauthnPubkeyHex != rhs.webauthnPubkeyHex {
            return false
        }
        if lhs.label != rhs.label {
            return false
        }
        if lhs.isThisDevice != rhs.isThisDevice {
            return false
        }
        if lhs.reprs != rhs.reprs {
            return false
        }
        if lhs.evmEnrollRepr != rhs.evmEnrollRepr {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(webauthnPubkeyHex)
        hasher.combine(label)
        hasher.combine(isThisDevice)
        hasher.combine(reprs)
        hasher.combine(evmEnrollRepr)
    }
}



