extension PairingQr: Sendable {}
#endif


extension PairingQr: Equatable, Hashable {
    public static func ==(lhs: PairingQr, rhs: PairingQr) -> Bool {
        if lhs.relayUrl != rhs.relayUrl {
            return false
        }
        if lhs.channelToken != rhs.channelToken {
            return false
        }
        if lhs.ephemeralPublicKey != rhs.ephemeralPublicKey {
            return false
        }
        if lhs.wallet != rhs.wallet {
            return false
        }
        if lhs.p256Pubkey != rhs.p256Pubkey {
            return false
        }
        if lhs.mode != rhs.mode {
            return false
        }
        if lhs.chainFamily != rhs.chainFamily {
            return false
        }
        if lhs.agentName != rhs.agentName {
            return false
        }
        if lhs.clientPlatform != rhs.clientPlatform {
            return false
        }
        if lhs.clientHostName != rhs.clientHostName {
            return false
        }
        if lhs.delegateDid != rhs.delegateDid {
            return false
        }
        if lhs.transportDid != rhs.transportDid {
