/**
 * The prepare-time fee quote. Amounts are USDC base-unit decimal strings
 * (JSON-number-loss-free); the owner signs `(fee_receiver, max_fee)` into the
 * op's canonical message and the guard CPIs `transfer_checked(actual_fee)` to
 * `fee_receiver`, enforcing `actual_fee <= max_fee <= cap` on chain.
 */
public struct SolanaFeeQuote {
    /**
     * The account the guard's reimbursement must credit -- Kora's advertised
     * payment account. The owner signs this as `fee_receiver`.
     */
    public var feeReceiver: String
    /**
     * Kora's SOL fee-payer (base58): it fills carrier slot 0, signs, and
     * submits, and is the account that fronts any rent.
     */
    public var feePayer: String
    /**
     * What the op charges (USDC base units): the core's schedule for the op
     * at the pinned SOL price, clamped to the cap. For `add_agent` the most it
     * charges; the prepare reports what it bound.
     */
    public var estimateUsdc: String
    /**
     * The signing ceiling (`max_fee`) the prepare binds, equal to
     * `estimate_usdc`.
     */
    public var maxFeeSuggested: String
    /**
     * The on-chain per-op fee cap.
     */
    public var cap: String
    /**
     * The part of the true network cost above the cap, which the wallet is
     * not asked for and Paygent absorbs; "0" until the SOL price pushes the
     * op's rent past the cap. Show it when nonzero.
     */
    public var uncoveredUsdc: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The account the guard's reimbursement must credit -- Kora's advertised
         * payment account. The owner signs this as `fee_receiver`.
         */feeReceiver: String, 
        /**
         * Kora's SOL fee-payer (base58): it fills carrier slot 0, signs, and
         * submits, and is the account that fronts any rent.
         */feePayer: String, 
        /**
         * What the op charges (USDC base units): the core's schedule for the op
         * at the pinned SOL price, clamped to the cap. For `add_agent` the most it
         * charges; the prepare reports what it bound.
         */estimateUsdc: String, 
        /**
         * The signing ceiling (`max_fee`) the prepare binds, equal to
         * `estimate_usdc`.
         */maxFeeSuggested: String, 
        /**
         * The on-chain per-op fee cap.
         */cap: String, 
        /**
         * The part of the true network cost above the cap, which the wallet is
         * not asked for and Paygent absorbs; "0" until the SOL price pushes the
         * op's rent past the cap. Show it when nonzero.
         */uncoveredUsdc: String) {
        self.feeReceiver = feeReceiver
        self.feePayer = feePayer
        self.estimateUsdc = estimateUsdc
        self.maxFeeSuggested = maxFeeSuggested
        self.cap = cap
        self.uncoveredUsdc = uncoveredUsdc
    }
}

#if compiler(>=6)
extension SolanaFeeQuote: Sendable {}
#endif


extension SolanaFeeQuote: Equatable, Hashable {
    public static func ==(lhs: SolanaFeeQuote, rhs: SolanaFeeQuote) -> Bool {
        if lhs.feeReceiver != rhs.feeReceiver {
            return false
        }
        if lhs.feePayer != rhs.feePayer {
            return false
        }
        if lhs.estimateUsdc != rhs.estimateUsdc {
            return false
        }
        if lhs.maxFeeSuggested != rhs.maxFeeSuggested {
            return false
        }
        if lhs.cap != rhs.cap {
            return false
        }
        if lhs.uncoveredUsdc != rhs.uncoveredUsdc {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(feeReceiver)
        hasher.combine(feePayer)
        hasher.combine(estimateUsdc)
        hasher.combine(maxFeeSuggested)
        hasher.combine(cap)
        hasher.combine(uncoveredUsdc)
    }
}



