         */mint: String, 
        /**
         * Enrolled owners in slot order (owner 0 first); `len == owner_count`.
         */owners: [SolanaGuardOwnerFfi], 
        /**
         * M-of-N owner-signing threshold.
         */threshold: UInt8, 
        /**
         * Number of enrolled owners (`== owners.len()`).
         */ownerCount: UInt8, 
        /**
         * Guard control-plane nonce (decimal string), for display.
         */nonce: String) {
        self.guardPda = guardPda
        self.vault = vault
        self.mint = mint
        self.owners = owners
        self.threshold = threshold
        self.ownerCount = ownerCount
        self.nonce = nonce
    }
}

