/**
 * Result of a WebAuthn owner-op `prepare`: the Merkle-root challenge the app
 * passes to `getAssertion`, the opaque completion token, the generated
 * `requestId`, and the resolved guard PDA for the approval prompt.
 */
public struct SolanaWebAuthnOwnerOpPrep {
    /**
     * 32-byte op Merkle root. The app's WebAuthn `getAssertion` uses this as
     * the challenge; the authenticator embeds `base64url(root)` into the
     * signed `clientDataJSON`.
     */
    public var challenge: Data
    /**
     * Opaque state for [`complete_solana_owner_op_webauthn`].
     */
    public var sessionToken: String
    /**
     * Generated `requestId` carried in the `OwnerOpRequest`.
     */
    public var requestId: String
    /**
     * Resolved guard PDA, base58 (for the approval prompt).
     */
    public var guardPda: String
    /**
     * The schedule this session bound: what the wallet pays and the ceiling
     * the signature authorizes. Returned rather than taken so the host shows
     * exactly what the owner is about to sign.
     */
    public var fees: SolanaOwnerOpFees

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * 32-byte op Merkle root. The app's WebAuthn `getAssertion` uses this as
         * the challenge; the authenticator embeds `base64url(root)` into the
         * signed `clientDataJSON`.
         */challenge: Data, 
        /**
         * Opaque state for [`complete_solana_owner_op_webauthn`].
         */sessionToken: String, 
        /**
         * Generated `requestId` carried in the `OwnerOpRequest`.
         */requestId: String, 
        /**
         * Resolved guard PDA, base58 (for the approval prompt).
         */guardPda: String, 
        /**
         * The schedule this session bound: what the wallet pays and the ceiling
         * the signature authorizes. Returned rather than taken so the host shows
         * exactly what the owner is about to sign.
         */fees: SolanaOwnerOpFees) {
        self.challenge = challenge
        self.sessionToken = sessionToken
        self.requestId = requestId
        self.guardPda = guardPda
        self.fees = fees
    }
}

