     * 32-byte big-endian P256 S value (post low-S normalisation).
     */
    public var s: Data

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(authenticatorData: Data, clientDataJson: Data, 
        /**
         * 32-byte big-endian P256 R value (post low-S normalisation).
         */r: Data, 
        /**
         * 32-byte big-endian P256 S value (post low-S normalisation).
         */s: Data) {
        self.authenticatorData = authenticatorData
        self.clientDataJson = clientDataJson
        self.r = r
        self.s = s
    }
}

#if compiler(>=6)
extension WebAuthnAssertionFfi: Sendable {}
#endif


extension WebAuthnAssertionFfi: Equatable, Hashable {
    public static func ==(lhs: WebAuthnAssertionFfi, rhs: WebAuthnAssertionFfi) -> Bool {
        if lhs.authenticatorData != rhs.authenticatorData {
            return false
        }
        if lhs.clientDataJson != rhs.clientDataJson {
            return false
        }
        if lhs.r != rhs.r {
            return false
        }
        if lhs.s != rhs.s {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(authenticatorData)
        hasher.combine(clientDataJson)
        hasher.combine(r)
        hasher.combine(s)
    }
}



