        switch variant {
        
        case 1: return .deviceHardware(kind: try FfiConverterTypeAgentHardwareKind.read(from: &buf)
        )
        
        case 2: return .relayOnly
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AgentSignerBacking, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .deviceHardware(kind):
            writeInt(&buf, Int32(1))
            FfiConverterTypeAgentHardwareKind.write(kind, into: &buf)
            
        
        case .relayOnly:
            writeInt(&buf, Int32(2))
        
        }
    }
}


