/**
 * FFI mirror of [`InboundMessage`].
 */

public enum InboundRelayMessage {
    
    case signRequest(subject: String, requestId: String, payload: EncryptedEnvelopeFfi
    )
    case approvalRequest(subject: String, payload: EncryptedEnvelopeFfi
    )
    case ownerOp(subject: String, payload: EncryptedEnvelopeFfi
    )
    case requestCancelled(subject: String, requestId: String, reason: String?
    )
    case error(code: String, message: String, requestId: String?, serverTimeMs: Int64?
    )
    /**
     * A frame that parsed but that an authorizer does nothing with. Carries the
     * type so the host can log which one it was.
     */
    case ignored(messageType: String
    )
}


#if compiler(>=6)
extension InboundRelayMessage: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeInboundRelayMessage: FfiConverterRustBuffer {
    typealias SwiftType = InboundRelayMessage

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> InboundRelayMessage {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .signRequest(subject: try FfiConverterString.read(from: &buf), requestId: try FfiConverterString.read(from: &buf), payload: try FfiConverterTypeEncryptedEnvelopeFfi.read(from: &buf)
        )
        
        case 2: return .approvalRequest(subject: try FfiConverterString.read(from: &buf), payload: try FfiConverterTypeEncryptedEnvelopeFfi.read(from: &buf)
        )
        
        case 3: return .ownerOp(subject: try FfiConverterString.read(from: &buf), payload: try FfiConverterTypeEncryptedEnvelopeFfi.read(from: &buf)
        )
        
        case 4: return .requestCancelled(subject: try FfiConverterString.read(from: &buf), requestId: try FfiConverterString.read(from: &buf), reason: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 5: return .error(code: try FfiConverterString.read(from: &buf), message: try FfiConverterString.read(from: &buf), requestId: try FfiConverterOptionString.read(from: &buf), serverTimeMs: try FfiConverterOptionInt64.read(from: &buf)
        )
        
        case 6: return .ignored(messageType: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: InboundRelayMessage, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .signRequest(subject,requestId,payload):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(subject, into: &buf)
            FfiConverterString.write(requestId, into: &buf)
            FfiConverterTypeEncryptedEnvelopeFfi.write(payload, into: &buf)
            
        
        case let .approvalRequest(subject,payload):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(subject, into: &buf)
            FfiConverterTypeEncryptedEnvelopeFfi.write(payload, into: &buf)
            
        
        case let .ownerOp(subject,payload):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(subject, into: &buf)
            FfiConverterTypeEncryptedEnvelopeFfi.write(payload, into: &buf)
            
        
        case let .requestCancelled(subject,requestId,reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(subject, into: &buf)
            FfiConverterString.write(requestId, into: &buf)
            FfiConverterOptionString.write(reason, into: &buf)
            
        
        case let .error(code,message,requestId,serverTimeMs):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            FfiConverterOptionString.write(requestId, into: &buf)
            FfiConverterOptionInt64.write(serverTimeMs, into: &buf)
            
        
        case let .ignored(messageType):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(messageType, into: &buf)
            
        }
    }
}


