    typealias SwiftType = MppKeychainAction

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MppKeychainAction {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .addAdminKey(adminPublicKey: try FfiConverterString.read(from: &buf), signatureType: try FfiConverterUInt8.read(from: &buf), witness: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 2: return .revokeKey(keyId: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .updateLimit(keyId: try FfiConverterString.read(from: &buf), token: try FfiConverterString.read(from: &buf), newLimit: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MppKeychainAction, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .addAdminKey(adminPublicKey,signatureType,witness):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(adminPublicKey, into: &buf)
            FfiConverterUInt8.write(signatureType, into: &buf)
            FfiConverterOptionString.write(witness, into: &buf)
            
        
        case let .revokeKey(keyId):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(keyId, into: &buf)
            
        
        case let .updateLimit(keyId,token,newLimit):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(keyId, into: &buf)
            FfiConverterString.write(token, into: &buf)
            FfiConverterString.write(newLimit, into: &buf)
            
        }
    }
}


