/**
 * FFI mirror of `paygent_multichain::PerChainStatus`.
 *
 * Kotlin/Native side matches on the variant to drive UI affordances:
 * `Submitted` → progress, `FailedTransient { can_retry: true }` → Continue
 * sheet (fresh biometric reuses the deterministic merkle root),
 * `FailedPermanent` / `LockedAfterMaxAttempts` → terminal copy.
 */

public enum PerChainStatusFfi {
    
    case submitted(chainId: UInt64, userOpHash: String, txHash: String?
    )
    case skipped(chainId: UInt64, reason: String
    )
    case failedTransient(chainId: UInt64, attempts: UInt32, lastReason: String, canRetry: Bool
    )
    case failedPermanent(chainId: UInt64, code: ErrorCodeFfi, reason: String, userActionable: UserActionFfi?
    )
    case lockedAfterMaxAttempts(chainId: UInt64
    )
}


#if compiler(>=6)
extension PerChainStatusFfi: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePerChainStatusFfi: FfiConverterRustBuffer {
    typealias SwiftType = PerChainStatusFfi

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PerChainStatusFfi {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .submitted(chainId: try FfiConverterUInt64.read(from: &buf), userOpHash: try FfiConverterString.read(from: &buf), txHash: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 2: return .skipped(chainId: try FfiConverterUInt64.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .failedTransient(chainId: try FfiConverterUInt64.read(from: &buf), attempts: try FfiConverterUInt32.read(from: &buf), lastReason: try FfiConverterString.read(from: &buf), canRetry: try FfiConverterBool.read(from: &buf)
        )
        
        case 4: return .failedPermanent(chainId: try FfiConverterUInt64.read(from: &buf), code: try FfiConverterTypeErrorCodeFfi.read(from: &buf), reason: try FfiConverterString.read(from: &buf), userActionable: try FfiConverterOptionTypeUserActionFfi.read(from: &buf)
        )
        
        case 5: return .lockedAfterMaxAttempts(chainId: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PerChainStatusFfi, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .submitted(chainId,userOpHash,txHash):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(chainId, into: &buf)
            FfiConverterString.write(userOpHash, into: &buf)
            FfiConverterOptionString.write(txHash, into: &buf)
            
        
        case let .skipped(chainId,reason):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(chainId, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .failedTransient(chainId,attempts,lastReason,canRetry):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(chainId, into: &buf)
            FfiConverterUInt32.write(attempts, into: &buf)
            FfiConverterString.write(lastReason, into: &buf)
            FfiConverterBool.write(canRetry, into: &buf)
            
        
        case let .failedPermanent(chainId,code,reason,userActionable):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(chainId, into: &buf)
            FfiConverterTypeErrorCodeFfi.write(code, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            FfiConverterOptionTypeUserActionFfi.write(userActionable, into: &buf)
            
        
        case let .lockedAfterMaxAttempts(chainId):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(chainId, into: &buf)
            
        }
    }
}


