@_documentation(visibility: private)
#endif
public func FfiConverterTypePerChainStatusFfi_lift(_ buf: RustBuffer) throws -> PerChainStatusFfi {
    return try FfiConverterTypePerChainStatusFfi.lift(buf)
}

