        case 1: return .text(text: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .calendar(timestampMs: try FfiConverterInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
