public enum SignRequestKind {
    
    case authorizePairing(challengeB64url: String, walletAddress: String, nonce: String, 
        /**
         * The requesting machine's own name for itself, bound into the
         * signed challenge when present.
         */deviceLabel: UntrustedText?
    )
    /**
     * Connect another of the owner's devices. The offer's signature was
     * checked when the request was read; approving runs the add-device plan
     * on this phone and sends no signed response.
     */
    case connectDevice(deviceName: UntrustedText, p256PubkeyHex: String, evmWebauthnSigner: String, solanaOwnerHex: String, ownerDid: String, expiresAtMs: Int64
    )
    /**
     * Set up a new account on this phone. Approving starts account creation
     * here and sends no signed response.
     */
    case setUpAccount(accountName: UntrustedText?, chainIds: [UInt64], solanaClusters: [String], requestedBy: UntrustedText?
    )
    case transfer(intentId: String, chainId: UInt64, safe: String, signer: String, to: String, amount: String, token: String, rail: TransferRail
    )
    /**
     * `cctp_transport` (RFC-0046): self-to-self cross-chain USDC transport --
     * the owner-signed EVM burn. `to` is the user's own destination-chain
     * account (32-byte mintRecipient, 0x-hex); `destination_domain` is Circle's
     * chain numbering.
     */
    case cctpTransport(intentId: String, chainId: UInt64, safe: String, signer: String, to: String, amount: String, destinationDomain: UInt32
    )
    case x402PaymentErc4337(intentId: String, chainId: UInt64, safe: String, signer: String, payTo: String, amount: String, asset: String
    )
    case x402PaymentEip3009(intentId: String, chainId: UInt64, safe: String, signer: String, payTo: String, amount: String, asset: String, maxTimeoutSeconds: UInt64, eip712DomainName: String, eip712DomainVersion: String
    )
    case solanaTransfer(intentId: String, cluster: String, walletAddress: String, to: String, amount: String, mintAddress: String
    )
    case solanaEscalateRefill(intentId: String, cluster: String, walletAddress: String, mintAddress: String, agent: String, amount: String, payTo: String?, 
        /**
         * Agent-supplied context. [`UntrustedText`], not `String`, so a screen
         * cannot bind it to a label without first choosing between what
         * arrived and what is safe to show.
         */resourceUrl: UntrustedText?, resourceDescription: UntrustedText?
    )
    /**
     * Lightning side-wallet top-up (RFC-0040 W4). No amount field on purpose:
     * the core reads it out of `invoice` and puts it in the display fields, so
     * the number the owner sees cannot be a value the daemon chose.
     * `side_wallet_index` selects which of the daemon's own pockets is
     * credited, and the device re-derives that pocket's node id from it, so an
     * invoice signed by anything else is refused rather than paid.
     */
    case lightningEscalateRefill(intentId: String, sideWalletIndex: UInt32, invoice: String, peerAddress: String, resourceDescription: UntrustedText?
    )
    /**
     * MPP `charge` on Tempo (RFC-0050). `pay_to`, `amount` and `currency` are
     * derived from the resource server's challenge by the core, not supplied
     * by the daemon.
     */
    case mppCharge(intentId: String, 
        /**
         * The server's challenge verbatim, echoed back inside the credential.
         * A `String` because sanitising it would change what is echoed. It is
         * protocol material, not label material -- the values a screen shows
         * are parsed out of it into the fields below.
         */challengeHeader: String, 
        /**
         * A `String` rather than an [`UntrustedText`] because the core
         * re-reads this exact field: `paygent_mpp::validate_charge_challenge`
         * parses it and refuses the charge unless the challenge's `realm`
         * names the same host, so handing it a sanitised value would break the
         * comparison it exists for.
         *
         * That check reaches the HOST and nothing else. The path, the query
         * and the fragment are unconstrained agent-supplied text: a screen
         * should render the host rather than the whole string, because the
         * whole string can carry the direction overrides and zero-width runs
         * that [`UntrustedText`] exists to strip from the fields beside it.
         * Daemon-supplied context either way, never a verified fact.
         */resourceUrl: String, resourceDescription: UntrustedText?, payTo: String, amount: String, currency: String, sender: String, chainId: UInt64, maxFeePerGas: String, maxPriorityFeePerGas: String
    )
    /**
     * MPP Tempo onboarding (RFC-0050): authorize the daemon's agent key on the
     * owner's Tempo account with an on-chain spending limit.
     */
    case mppOnboard(intentId: String, account: String, agentPublicKey: String, limits: [MppTokenLimit], chainId: UInt64, nonce: UInt64, maxFeePerGas: String, maxPriorityFeePerGas: String
    )
    /**
     * MPP Tempo wallet-lifecycle owner op (RFC-0050): the whole owner/limit
     * surface on Tempo (add owner key / revoke key / change limit). No recovery
     * ceremony, no rotation, no M-of-N -- a backup admin key IS the recovery
     * story.
     */
    case mppKeychain(intentId: String, account: String, chainId: UInt64, nonce: UInt64, maxFeePerGas: String, maxPriorityFeePerGas: String, action: MppKeychainAction
    )
}


