@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSolanaGuardOp: FfiConverterRustBuffer {
    typealias SwiftType = SolanaGuardOp

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SolanaGuardOp {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .setLimit
        
        case 2: return .refill
        
        case 3: return .revoke
        
        case 4: return .withdraw
        
        case 5: return .addAgent
        
        case 6: return .setAgentLimit
        
        case 7: return .removeAgent
        
        case 8: return .addOwner
        
        case 9: return .removeOwner
        
        case 10: return .escalateRefill
        
        case 11: return .setThreshold
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SolanaGuardOp, into buf: inout [UInt8]) {
        switch value {
        
        
        case .setLimit:
            writeInt(&buf, Int32(1))
        
        
        case .refill:
            writeInt(&buf, Int32(2))
        
        
        case .revoke:
            writeInt(&buf, Int32(3))
        
        
        case .withdraw:
            writeInt(&buf, Int32(4))
        
        
        case .addAgent:
            writeInt(&buf, Int32(5))
        
        
        case .setAgentLimit:
            writeInt(&buf, Int32(6))
        
        
        case .removeAgent:
            writeInt(&buf, Int32(7))
        
        
        case .addOwner:
            writeInt(&buf, Int32(8))
        
        
        case .removeOwner:
            writeInt(&buf, Int32(9))
        
        
        case .escalateRefill:
            writeInt(&buf, Int32(10))
        
        
        case .setThreshold:
            writeInt(&buf, Int32(11))
        
        }
    }
}


