        switch variant {
        
        case 1: return .raw
        
        case 2: return .webAuthn
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SolanaOwnerMode, into buf: inout [UInt8]) {
        switch value {
        
        
        case .raw:
            writeInt(&buf, Int32(1))
        
        
        case .webAuthn:
            writeInt(&buf, Int32(2))
        
        }
    }
}


